create extension if not exists pgcrypto;
create table if not exists public.projects(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null check(char_length(name) between 2 and 140),description text not null default '',status text not null default 'planning' check(status in('planning','active','completed','archived')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.tasks(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,title text not null check(char_length(title) between 2 and 180),description text not null default '',status text not null default 'todo' check(status in('todo','in_progress','done')),priority text not null default 'medium' check(priority in('low','medium','high')),due_date date,created_at timestamptz not null default now());
create table if not exists public.user_preferences(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,preference_key text not null,preference_value jsonb not null,confidence numeric(4,3) not null default 0 check(confidence between 0 and 1),updated_at timestamptz not null default now(),unique(user_id,preference_key));
create table if not exists public.user_events(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,session_id text not null,event_type text not null,payload jsonb not null default '{}',created_at timestamptz not null default now());
alter table public.projects enable row level security; alter table public.tasks enable row level security; alter table public.user_preferences enable row level security; alter table public.user_events enable row level security;
create policy "project owner" on public.projects for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "task owner" on public.tasks for all using(auth.uid()=user_id and exists(select 1 from public.projects p where p.id=project_id and p.user_id=auth.uid())) with check(auth.uid()=user_id and exists(select 1 from public.projects p where p.id=project_id and p.user_id=auth.uid()));
create policy "preference owner" on public.user_preferences for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "event owner" on public.user_events for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
